using System.Text.Json;using Orchestration.API.Engineering.Intelligence;
namespace Orchestration.API.Tests.Engineering.Intelligence;
public sealed class Aud001To005ClosureTests{
 public static IEnumerable<object[]> Fixtures(){foreach(var p in new[]{"hydraulic-pump","medical-cart","industrial-robot"})foreach(var m in new[]{"complete","partial","deep","multi-source","attribute-variation"})yield return new object[]{p,m};}
 [Theory][MemberData(nameof(Fixtures))]public void Fifteen_fixture_variations_are_canonical(string product,string mode){var result=new LegacyHandoffCanonicalAssembler().Assemble(Fixture(product,mode));Assert.Equal("1.0",result.ContractVersion);Assert.NotEmpty(result.Entities);Assert.All(result.Sources,x=>Assert.False(string.IsNullOrWhiteSpace(x.NativeId)));if(mode=="partial")Assert.Equal(1,result.Summary.PartialSourceCount);}
 [Fact]public void Malformed_handoff_fails_explicitly()=>Assert.Throws<ArgumentException>(()=>new LegacyHandoffCanonicalAssembler().Assemble(JsonDocument.Parse("{\"version\":2}").RootElement));
 static JsonElement Fixture(string product,string mode){var child=mode=="deep"?"{\"id\":\"C1\",\"name\":\"Child\",\"attributes\":{},\"children\":[{\"id\":\"L1\",\"name\":\"Leaf\",\"attributes\":{},\"children\":[]}]}":"{\"id\":\"C1\",\"name\":\"Child\",\"attributes\":{},\"children\":[]}";var second=mode=="multi-source"?",{\"source\":\"sap\",\"label\":\"SAP\",\"nativeId\":\"MAT-200\",\"completeness\":\"complete\",\"root\":{\"id\":\"MAT-200\",\"name\":\"Material\",\"attributes\":{},\"children\":[]}}":"";return JsonDocument.Parse($"{{\"version\":2,\"handoffId\":\"{product}-{mode}\",\"createdAt\":\"2026-09-16T00:00:00Z\",\"subjectLabel\":\"{product}\",\"sources\":[{{\"source\":\"windchill\",\"label\":\"Windchill\",\"nativeId\":\"PART-100\",\"completeness\":\"{(mode=="partial"?"partial":"complete")}\",\"root\":{{\"id\":\"PART-100\",\"name\":\"{product}\",\"attributes\":{{\"Revision\":\"A\"}},\"children\":[{child}]}}}}{second}]}}").RootElement.Clone();}}
